package com.kaymlyn.planeteater.simulation.celestial;

import com.kaymlyn.planeteater.simulation.physics.PhysicsConstants;
import com.kaymlyn.planeteater.simulation.physics.Vector3D;
import lombok.Getter;
import lombok.Setter;

/**
 * Stores position and velocity - orbital elements are calculated on demand.
 *
 * Generated by Claude (Sonnet 4.5) - Architecture Refactor
 */
@Getter
@Setter
public abstract class OrbitingBody implements Orbiter {

    protected String id;
    protected Vector3D position;
    protected Vector3D velocity;

    public OrbitingBody(String id, Vector3D position, Vector3D velocity, Gravitational parentBody) {
        this.id = id;
        this.position = position != Vector3D.ZERO ? position : Vector3D.randomUnitVector();
        this.velocity = velocity != Vector3D.ZERO ? velocity : Vector3D.randomUnitVector();
    }

    public double getMass() {
        return getAggregatedMass();
    }

    protected abstract double getAggregatedMass();

    public abstract double getRadius();

    public abstract double getDensity();

    public void update(Vector3D acceleration, double dt) {
        velocity = velocity.add(acceleration.multiply(dt));
        position = position.add(velocity.multiply(dt));
    }

    public double getCircularOrbitVelocity(double radius) {
        return Math.sqrt(PhysicsConstants.G * this.getMass() / radius);
    }

    public double orbitalPeriod(double radius) {
        return 2.0 * Math.PI * Math.sqrt(Math.pow(radius, 3) /
                (PhysicsConstants.G * this.getMass()));
    }

    public abstract double getVolume();

    @Override
    public String toString() {
        return String.format("%s[id=%s, pos=%s, vel=%s, mass=%.3e kg, radius=%.3e m]",
                getClass().getSimpleName(), id, position, velocity, getMass(), getRadius());
    }
}